// The state of an OAuth app install.
type OAuthAppInstallState string

const (
	// The integration exists but no user has completed consent. Every operation is refused with an `authorization-required` problem until consent completes.
	OAuthAppInstallStatePendingAuthorization OAuthAppInstallState = "pending_authorization"
	// The app is installed and holds every permission it requires.
	OAuthAppInstallStateActive OAuthAppInstallState = "active"
	// The app is installed but has not been granted every permission it requires. Authorize again to re-consent.
	OAuthAppInstallStateNeedsReconsent OAuthAppInstallState = "needs_reconsent"
	// The app install was removed or disabled in the vendor.
	OAuthAppInstallStateRevoked OAuthAppInstallState = "revoked"
)

func NewOAuthAppInstallStateFromString(s string) (OAuthAppInstallState, error) {
	switch s {
	case "pending_authorization":
		return OAuthAppInstallStatePendingAuthorization, nil
	case "active":
		return OAuthAppInstallStateActive, nil
	case "needs_reconsent":
		return OAuthAppInstallStateNeedsReconsent, nil
	case "revoked":
		return OAuthAppInstallStateRevoked, nil
	}
	var t OAuthAppInstallState
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

func (o OAuthAppInstallState) Ptr() *OAuthAppInstallState {
	return &o
}

